using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;

namespace Sessions.Core;

// One open VS Code window drawn from windowsState: a folder or a .code-workspace file
public sealed record VsCodeWindow(string Path, bool IsWorkspace)
{
    // The name VS Code shows as rootName in the window title, used to match a title to this window
    public string DisplayName => IsWorkspace
        ? System.IO.Path.GetFileNameWithoutExtension(Path) + " (Workspace)"
        : System.IO.Path.GetFileName(Path.TrimEnd('\\', '/'));
}

// Pure helpers for resolving which folder (or workspace file) a VS Code window has open,
// from the globalStorage windowsState plus the window title, see docs/spikes/vscode.md
public static class VsCodeStorage
{
    private const string TitleSuffix = " - Visual Studio Code";

    // Reads windowsState from a storage.json body into a flat list of open windows,
    // lastActiveWindow and every openedWindows entry are treated uniformly, empty
    // windows (no folder, no workspace) are skipped
    public static IReadOnlyList<VsCodeWindow> ParseWindows(string storageJson)
    {
        List<VsCodeWindow> windows = new();

        using JsonDocument doc = JsonDocument.Parse(storageJson);
        if (!doc.RootElement.TryGetProperty("windowsState", out JsonElement state))
        {
            return windows;
        }

        if (state.TryGetProperty("lastActiveWindow", out JsonElement last) && last.ValueKind == JsonValueKind.Object)
        {
            AddWindow(windows, last);
        }

        if (state.TryGetProperty("openedWindows", out JsonElement opened) && opened.ValueKind == JsonValueKind.Array)
        {
            foreach (JsonElement window in opened.EnumerateArray())
            {
                AddWindow(windows, window);
            }
        }

        return windows;
    }

    private static void AddWindow(List<VsCodeWindow> windows, JsonElement window)
    {
        if (window.TryGetProperty("folder", out JsonElement folder) && folder.ValueKind == JsonValueKind.String)
        {
            string? path = DecodeFileUri(folder.GetString());
            if (path is not null)
            {
                windows.Add(new VsCodeWindow(path, IsWorkspace: false));
            }

            return;
        }

        if (window.TryGetProperty("workspace", out JsonElement workspace) &&
            workspace.ValueKind == JsonValueKind.Object &&
            workspace.TryGetProperty("configPath", out JsonElement configPath) &&
            configPath.ValueKind == JsonValueKind.String)
        {
            string? path = DecodeFileUri(configPath.GetString());
            if (path is not null)
            {
                windows.Add(new VsCodeWindow(path, IsWorkspace: true));
            }
        }

        // Otherwise an empty window, nothing to restore
    }

    // Resolves the folder or workspace path the given window title refers to, or null
    // when nothing matches or two candidates share the title's root name (ambiguous)
    public static string? Resolve(string windowTitle, IReadOnlyList<VsCodeWindow> windows)
    {
        string? rootName = RootNameFromTitle(windowTitle);
        if (rootName is null)
        {
            return null;
        }

        List<VsCodeWindow> matches = windows
            .Where(w => string.Equals(w.DisplayName, rootName, StringComparison.OrdinalIgnoreCase))
            .ToList();

        return matches.Count == 1 ? matches[0].Path : null;
    }

    // The rootName segment of a default VS Code title, the part just before
    // " - Visual Studio Code", null if the title isn't in that shape (custom template)
    public static string? RootNameFromTitle(string title)
    {
        if (string.IsNullOrEmpty(title) || !title.EndsWith(TitleSuffix, StringComparison.Ordinal))
        {
            return null;
        }

        string head = title[..^TitleSuffix.Length].Trim();
        if (head.Length == 0)
        {
            return null;
        }

        // Template is "${activeEditorShort} - ${rootName}", rootName is the last " - " segment,
        // or the whole head when no file is open ("sessions - Visual Studio Code")
        int lastSep = head.LastIndexOf(" - ", StringComparison.Ordinal);
        string rootName = lastSep >= 0 ? head[(lastSep + 3)..] : head;
        return rootName.Length == 0 ? null : rootName;
    }

    // Decodes a VS Code file:// URI to a Windows path, e.g.
    // file:///c%3A/Users/ZEPHYRUS%20G14/Desktop/sessions -> c:\Users\ZEPHYRUS G14\Desktop\sessions
    public static string? DecodeFileUri(string? uri)
    {
        const string prefix = "file://";
        if (string.IsNullOrEmpty(uri) || !uri.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
        {
            return null;
        }

        string rest = uri[prefix.Length..];

        // A local path is file:///<drive>..., a UNC path is file://server/share
        if (rest.StartsWith('/'))
        {
            string decoded = Uri.UnescapeDataString(rest[1..]);
            return decoded.Replace('/', '\\');
        }

        return @"\\" + Uri.UnescapeDataString(rest).Replace('/', '\\');
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class VsCodeStorageTests
{
    // The real sample captured in docs/spikes/vscode.md
    private const string FolderStorage =
        """
        {
          "windowsState": {
            "lastActiveWindow": {
              "folder": "file:///c%3A/Users/ZEPHYRUS%20G14/Desktop/sessions",
              "uiState": { "mode": 0, "x": 548, "y": 87, "width": 1200, "height": 800 }
            },
            "openedWindows": []
          }
        }
        """;

    private const string WorkspaceStorage =
        """
        {
          "windowsState": {
            "lastActiveWindow": {
              "workspace": { "id": "abc", "configPath": "file:///c%3A/Users/me/proj/foo.code-workspace" }
            },
            "openedWindows": []
          }
        }
        """;

    [Theory]
    [InlineData("file:///c%3A/Users/ZEPHYRUS%20G14/Desktop/sessions", @"c:\Users\ZEPHYRUS G14\Desktop\sessions")]
    [InlineData("file:///c%3A/Users/me/proj/foo.code-workspace", @"c:\Users\me\proj\foo.code-workspace")]
    public void DecodeFileUri_DecodesDriveLocalPaths(string uri, string expected)
    {
        Assert.Equal(expected, VsCodeStorage.DecodeFileUri(uri));
    }

    [Fact]
    public void DecodeFileUri_NonFileUri_ReturnsNull()
    {
        Assert.Null(VsCodeStorage.DecodeFileUri("https://example.com"));
        Assert.Null(VsCodeStorage.DecodeFileUri(null));
    }

    [Fact]
    public void ParseWindows_FolderWindow_YieldsDecodedFolder()
    {
        var windows = VsCodeStorage.ParseWindows(FolderStorage);

        VsCodeWindow only = Assert.Single(windows);
        Assert.False(only.IsWorkspace);
        Assert.Equal(@"c:\Users\ZEPHYRUS G14\Desktop\sessions", only.Path);
        Assert.Equal("sessions", only.DisplayName);
    }

    [Fact]
    public void ParseWindows_WorkspaceWindow_YieldsConfigPath()
    {
        var windows = VsCodeStorage.ParseWindows(WorkspaceStorage);

        VsCodeWindow only = Assert.Single(windows);
        Assert.True(only.IsWorkspace);
        Assert.Equal(@"c:\Users\me\proj\foo.code-workspace", only.Path);
        Assert.Equal("foo (Workspace)", only.DisplayName);
    }

    [Fact]
    public void ParseWindows_EmptyWindow_IsSkipped()
    {
        const string json = """{ "windowsState": { "lastActiveWindow": { "uiState": {} }, "openedWindows": [] } }""";
        Assert.Empty(VsCodeStorage.ParseWindows(json));
    }

    [Fact]
    public void ParseWindows_NoWindowsState_IsEmpty()
    {
        Assert.Empty(VsCodeStorage.ParseWindows("{}"));
    }

    [Theory]
    [InlineData("AdapterRegistry.cs - sessions - Visual Studio Code", "sessions")]
    [InlineData("sessions - Visual Studio Code", "sessions")]
    [InlineData("Program.cs - foo (Workspace) - Visual Studio Code", "foo (Workspace)")]
    public void RootNameFromTitle_ExtractsRootName(string title, string expected)
    {
        Assert.Equal(expected, VsCodeStorage.RootNameFromTitle(title));
    }

    [Theory]
    [InlineData("Some Other App")]
    [InlineData("")]
    public void RootNameFromTitle_NonVsCode_ReturnsNull(string title)
    {
        Assert.Null(VsCodeStorage.RootNameFromTitle(title));
    }

    [Fact]
    public void Resolve_SingleFolderMatch_ReturnsPath()
    {
        var windows = VsCodeStorage.ParseWindows(FolderStorage);
        string? path = VsCodeStorage.Resolve("AdapterRegistry.cs - sessions - Visual Studio Code", windows);
        Assert.Equal(@"c:\Users\ZEPHYRUS G14\Desktop\sessions", path);
    }

    [Fact]
    public void Resolve_WorkspaceMatch_ReturnsConfigPath()
    {
        var windows = VsCodeStorage.ParseWindows(WorkspaceStorage);
        string? path = VsCodeStorage.Resolve("Program.cs - foo (Workspace) - Visual Studio Code", windows);
        Assert.Equal(@"c:\Users\me\proj\foo.code-workspace", path);
    }

    [Fact]
    public void Resolve_NoMatch_ReturnsNull()
    {
        var windows = VsCodeStorage.ParseWindows(FolderStorage);
        Assert.Null(VsCodeStorage.Resolve("x - other - Visual Studio Code", windows));
    }

    [Fact]
    public void Resolve_AmbiguousSameBaseName_ReturnsNull()
    {
        // Two different folders that share the base name "app" collide on rootName
        const string json =
            """
            {
              "windowsState": {
                "lastActiveWindow": { "folder": "file:///c%3A/a/app" },
                "openedWindows": [ { "folder": "file:///c%3A/b/app" } ]
              }
            }
            """;
        var windows = VsCodeStorage.ParseWindows(json);
        Assert.Equal(2, windows.Count);
        Assert.Null(VsCodeStorage.Resolve("main.cs - app - Visual Studio Code", windows));
    }
}

