using System.Diagnostics;
using System.IO;

namespace Sessions.Core;

// Captures and restores a VS Code window by its open folder or .code-workspace,
// resolved from globalStorage windowsState plus the window title, see
// docs/spikes/vscode.md, registered before GenericAdapter so Code.exe windows
// go here first
public sealed class VsCodeAdapter : IAdapter
{
    private const string CodeExeName = "Code.exe";

    private readonly Func<string?> _readStorageJson;
    private readonly IWindowWaiter _waiter;
    private readonly IWindowPlacer _placer;
    private readonly Action<string> _launch;

    public VsCodeAdapter()
        : this(ReadDefaultStorage, new WindowWaiter(), new WindowPlacer(), LaunchCode) { }

    public VsCodeAdapter(
        Func<string?> readStorageJson,
        IWindowWaiter waiter,
        IWindowPlacer placer,
        Action<string> launch)
    {
        _readStorageJson = readStorageJson ?? throw new ArgumentNullException(nameof(readStorageJson));
        _waiter = waiter ?? throw new ArgumentNullException(nameof(waiter));
        _placer = placer ?? throw new ArgumentNullException(nameof(placer));
        _launch = launch ?? throw new ArgumentNullException(nameof(launch));
    }

    // %APPDATA%\Code\User\globalStorage\storage.json
    public static string DefaultStoragePath => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
        "Code", "User", "globalStorage", "storage.json");

    public string Id => "vscode";

    // Handles supported Code.exe windows
    public bool CanHandle(WindowInfo window) =>
        window.UnsupportedReason is null && IsCodeExe(window.ExePath);

    public Entry Capture(WindowInfo window)
    {
        ArgumentNullException.ThrowIfNull(window);

        string? json = _readStorageJson();
        var windows = json is null
            ? Array.Empty<VsCodeWindow>()
            : VsCodeStorage.ParseWindows(json);

        string? path = VsCodeStorage.Resolve(window.Title, (IReadOnlyList<VsCodeWindow>)windows);
        if (path is null)
        {
            throw new CaptureException(
                $"{window.Title}: couldn't resolve the VS Code folder from windowsState.");
        }

        return new VsCodeEntry(DisplayNameFor(path), window.Placement, path);
    }

    public void Restore(Entry entry)
    {
        ArgumentNullException.ThrowIfNull(entry);

        if (entry is not VsCodeEntry vsCode)
        {
            throw new RestoreException($"{entry.DisplayName}: VsCodeAdapter cannot restore a {entry.GetType().Name}.");
        }

        if (string.IsNullOrEmpty(vsCode.Path))
        {
            throw new RestoreException($"{vsCode.DisplayName}: no path to open.");
        }

        try
        {
            _launch(vsCode.Path);
        }
        catch (Exception ex)
        {
            throw new RestoreException($"{vsCode.DisplayName}: failed to launch VS Code for '{vsCode.Path}'.", ex);
        }

        nint handle = _waiter.WaitForNewWindow(CodeExeName, vsCode.DisplayName);

        if (vsCode.Placement is not null)
        {
            _placer.Apply(handle, vsCode.Placement, targetElevated: false);
        }
    }

    private static bool IsCodeExe(string? exePath) =>
        exePath is not null &&
        string.Equals(Path.GetFileName(exePath), CodeExeName, StringComparison.OrdinalIgnoreCase);

    private static string DisplayNameFor(string path) =>
        path.EndsWith(".code-workspace", StringComparison.OrdinalIgnoreCase)
            ? Path.GetFileNameWithoutExtension(path) + " (Workspace)"
            : Path.GetFileName(path.TrimEnd('\\', '/'));

    private static string? ReadDefaultStorage()
    {
        try
        {
            return File.Exists(DefaultStoragePath) ? File.ReadAllText(DefaultStoragePath) : null;
        }
        catch (IOException)
        {
            return null;
        }
    }

    // Opens a new window on the path via the code CLI shim, the cmd wrapper lets
    // us run code.cmd without a visible console
    private static void LaunchCode(string path)
    {
        ProcessStartInfo startInfo = new("cmd.exe", $"/c code -n \"{path}\"")
        {
            UseShellExecute = false,
            CreateNoWindow = true,
        };
        Process.Start(startInfo);
    }
}

using Sessions.Core;

namespace Sessions.Tests;

public class VsCodeAdapterTests
{
    private const string FolderStorage =
        """
        {
          "windowsState": {
            "lastActiveWindow": { "folder": "file:///c%3A/Users/ZEPHYRUS%20G14/Desktop/sessions" },
            "openedWindows": []
          }
        }
        """;

    private static VsCodeAdapter Adapter(string? storageJson) =>
        new(() => storageJson, new NoWaiter(), new NoPlacer(), _ => { });

    private static WindowInfo CodeWindow(string title) =>
        new(Handle: 1, Title: title, ProcessId: 10)
        {
            ExePath = @"C:\Users\me\AppData\Local\Programs\Microsoft VS Code\Code.exe",
            Placement = new Placement(100, 100, 1200, 800, 1),
        };

    [Fact]
    public void CanHandle_CodeExe_IsTrue()
    {
        Assert.True(Adapter(FolderStorage).CanHandle(CodeWindow("x - sessions - Visual Studio Code")));
    }

    [Fact]
    public void CanHandle_OtherExe_IsFalse()
    {
        WindowInfo notCode = new(Handle: 1, Title: "x", ProcessId: 1) { ExePath = @"C:\Windows\notepad.exe" };
        Assert.False(Adapter(FolderStorage).CanHandle(notCode));
    }

    [Fact]
    public void CanHandle_UnsupportedWindow_IsFalse()
    {
        WindowInfo unsupported = CodeWindow("x - sessions - Visual Studio Code") with { UnsupportedReason = "nope" };
        Assert.False(Adapter(FolderStorage).CanHandle(unsupported));
    }

    [Fact]
    public void Capture_ResolvesFolder_IntoVsCodeEntry()
    {
        Entry entry = Adapter(FolderStorage).Capture(CodeWindow("AdapterRegistry.cs - sessions - Visual Studio Code"));

        VsCodeEntry vs = Assert.IsType<VsCodeEntry>(entry);
        Assert.Equal(@"c:\Users\ZEPHYRUS G14\Desktop\sessions", vs.Path);
        Assert.Equal("sessions", vs.DisplayName);
        Assert.Equal("vscode", vs.AdapterId);
        Assert.Equal(new Placement(100, 100, 1200, 800, 1), vs.Placement);
    }

    [Fact]
    public void Capture_UnresolvedTitle_Throws()
    {
        Assert.Throws<CaptureException>(() =>
            Adapter(FolderStorage).Capture(CodeWindow("x - other-folder - Visual Studio Code")));
    }

    [Fact]
    public void Capture_NoStorage_Throws()
    {
        Assert.Throws<CaptureException>(() =>
            Adapter(storageJson: null).Capture(CodeWindow("x - sessions - Visual Studio Code")));
    }

    [Fact]
    public void Registry_SelectsVsCode_BeforeGeneric_ForCodeExe()
    {
        AdapterRegistry registry = new(new IAdapter[] { Adapter(FolderStorage) }, new GenericAdapter());
        IAdapter? chosen = registry.SelectForCapture(CodeWindow("x - sessions - Visual Studio Code"));
        Assert.Equal("vscode", chosen?.Id);
    }

    private sealed class NoWaiter : IWindowWaiter
    {
        public nint WaitForNewWindow(string exePath, string displayName) => throw new InvalidOperationException();
    }

    private sealed class NoPlacer : IWindowPlacer
    {
        public void Apply(nint hwnd, Placement placement, bool targetElevated) => throw new InvalidOperationException();
    }
}

