98	    // " - Visual Studio Code", null if the title isn't in that shape (custom template)
99	    public static string? RootNameFromTitle(string title)
100	    {
101	        if (string.IsNullOrEmpty(title) || !title.EndsWith(TitleSuffix, StringComparison.Ordinal))
102	        {
103	            return null;
104	        }
105	
106	        string head = title[..^TitleSuffix.Length].Trim();
107	        if (head.Length == 0)
108	        {
109	            return null;
110	        }
111	
112	        // Template is "${activeEditorShort} - ${rootName}", rootName is the last " - " segment,
113	        // or the whole head when no file is open ("sessions - Visual Studio Code")
114	        int lastSep = head.LastIndexOf(" - ", StringComparison.Ordinal);
115	        string rootName = lastSep >= 0 ? head[(lastSep + 3)..] : head;
116	        return rootName.Length == 0 ? null : rootName;
117	    }
118	
119	    // Decodes a VS Code file:// URI to a Windows path, e.g.
120	    // file:///c%3A/Users/ZEPHYRUS%20G14/Desktop/sessions -> c:\Users\ZEPHYRUS G14\Desktop\sessions
121	    public static string? DecodeFileUri(string? uri)
122	    {
123	        const string prefix = "file://";
124	        if (string.IsNullOrEmpty(uri) || !uri.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
125	        {
126	            return null;
127	        }
128	
129	        string rest = uri[prefix.Length..];
130	
131	        // A local path is file:///<drive>..., a UNC path is file://server/share
132	        if (rest.StartsWith('/'))
133	        {
134	            string decoded = Uri.UnescapeDataString(rest[1..]);
135	            return decoded.Replace('/', '\\');
136	        }
137	
138	        return @"\\" + Uri.UnescapeDataString(rest).Replace('/', '\\');
