using System.Collections.Generic;
using System.Linq;
using System.Management;

namespace Sessions.Core;

// One process in a snapshot, Name is the image name (e.g. "claude.exe")
public sealed record ProcessInfo(uint Pid, uint ParentProcessId, string Name, string? CommandLine);

// A point-in-time view of the running processes, built once per capture so the
// parent walks stay consistent, the pure walks are testable from a hand-built list
public sealed class ProcessSnapshot
{
    private readonly IReadOnlyDictionary<uint, ProcessInfo> _byPid;

    public ProcessSnapshot(IEnumerable<ProcessInfo> processes)
    {
        // A snapshot can momentarily hold two rows for one pid, keep the first
        Dictionary<uint, ProcessInfo> byPid = new();
        foreach (ProcessInfo process in processes)
        {
            byPid.TryAdd(process.Pid, process);
        }

        _byPid = byPid;
    }

    public IReadOnlyCollection<ProcessInfo> Processes => (IReadOnlyCollection<ProcessInfo>)_byPid.Values;

    // True when the snapshot still holds this pid, a record for a missing pid is a
    // dead shell to drop
    public bool Contains(uint pid) => _byPid.ContainsKey(pid);

    public ProcessInfo? Get(uint pid) => _byPid.TryGetValue(pid, out ProcessInfo? info) ? info : null;

    // True when ancestorPid sits somewhere on pid's parent chain, the chain is
    // guarded against loops and a self-parent (pid reuse can forge either)
    public bool IsDescendantOf(uint pid, uint ancestorPid)
    {
        uint current = pid;
        for (int guard = 0; guard < 64; guard++)
        {
            if (!_byPid.TryGetValue(current, out ProcessInfo? info))
            {
                return false;
            }

            uint parent = info.ParentProcessId;
            if (parent == ancestorPid)
            {
                return true;
            }

            if (parent == 0 || parent == current)
            {
                return false;
            }

            current = parent;
        }

        return false;
    }

    // Every process whose parent chain passes through rootPid
    public IEnumerable<ProcessInfo> Descendants(uint rootPid) =>
        _byPid.Values.Where(p => IsDescendantOf(p.Pid, rootPid));

    // Reads the live process list via WMI, Name and ParentProcessId are always
    // present, CommandLine can be null when WMI withholds it
    public static ProcessSnapshot Capture()
    {
        List<ProcessInfo> processes = new();

        using var searcher = new ManagementObjectSearcher(
            "SELECT ProcessId, ParentProcessId, Name, CommandLine FROM Win32_Process");

        foreach (ManagementBaseObject mo in searcher.Get())
        {
            using (mo)
            {
                uint pid = Convert.ToUInt32(mo["ProcessId"]);
                uint parent = mo["ParentProcessId"] is { } p ? Convert.ToUInt32(p) : 0;
                string name = mo["Name"] as string ?? string.Empty;
                string? commandLine = mo["CommandLine"] as string;
                if (string.IsNullOrEmpty(commandLine))
                {
                    commandLine = null;
                }

                processes.Add(new ProcessInfo(pid, parent, name, commandLine));
            }
        }

        return new ProcessSnapshot(processes);
    }
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;

namespace Sessions.Core;

// A live shell as reported by the PowerShell hook (tools/terminal-hook), one file
// per pid under %APPDATA%\Sessions\terminals, see docs/spikes/terminal.md
public sealed record TerminalRecord(
    int Pid,
    string Cwd,
    string ShellPath,
    string? WtSession,
    DateTimeOffset Updated);

// Reads the hook's records and narrows them to the shells of one Windows Terminal
// window, the reader skips files it can't parse so one stale file never sinks a capture
public static class TerminalRecords
{
    // %APPDATA%\Sessions\terminals
    public static string DefaultDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
        "Sessions", "terminals");

    private static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web);

    public static IReadOnlyList<TerminalRecord> Read(string directory)
    {
        List<TerminalRecord> records = new();
        if (!Directory.Exists(directory))
        {
            return records;
        }

        foreach (string file in Directory.EnumerateFiles(directory, "*.json"))
        {
            try
            {
                TerminalRecord? record = JsonSerializer.Deserialize<TerminalRecord>(File.ReadAllText(file), Options);
                if (record is not null && !string.IsNullOrEmpty(record.Cwd))
                {
                    records.Add(record);
                }
            }
            catch (Exception ex) when (ex is JsonException or IOException)
            {
                // A half-written or stale file, skip it
            }
        }

        return records;
    }

    // Keeps the records whose pid is still alive and is a descendant of the given
    // WindowsTerminal.exe pid, so only this window's shells survive
    public static IReadOnlyList<TerminalRecord> ForWindowsTerminal(
        IEnumerable<TerminalRecord> records,
        ProcessSnapshot snapshot,
        uint windowsTerminalPid)
    {
        return records
            .Where(r => snapshot.Contains((uint)r.Pid) &&
                        snapshot.IsDescendantOf((uint)r.Pid, windowsTerminalPid))
            .OrderBy(r => r.Pid)
            .ToList();
    }
}

using System.Linq;

namespace Sessions.Core;

// Looks at what a shell is running to decide how to restore its tab, from the
// shell's process descendants, see docs/spikes/terminal.md
public static class TerminalShellInspector
{
    private const string ClaudeProcessName = "claude.exe";
    private const string SshProcessName = "ssh.exe";

    // IsClaude is true when a claude.exe runs under the shell, SshCommand is the
    // command line of an ssh.exe under the shell (so the tab can re-run it) or null
    public static (bool IsClaude, string? SshCommand) Inspect(ProcessSnapshot snapshot, uint shellPid)
    {
        bool isClaude = false;
        string? sshCommand = null;

        foreach (ProcessInfo descendant in snapshot.Descendants(shellPid))
        {
            if (Matches(descendant.Name, ClaudeProcessName))
            {
                isClaude = true;
            }
            else if (sshCommand is null && Matches(descendant.Name, SshProcessName))
            {
                sshCommand = descendant.CommandLine;
            }
        }

        return (isClaude, sshCommand);
    }

    private static bool Matches(string name, string target) =>
        string.Equals(name, target, StringComparison.OrdinalIgnoreCase);
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

namespace Sessions.Core;

// Finds the Claude Code session to resume for a terminal tab's working folder,
// Claude stores one .jsonl per session under a per-cwd project folder whose name
// encodes the cwd, the file name without its extension is the session id, see
// docs/spikes/terminal.md
public static class ClaudeSession
{
    // %USERPROFILE%\.claude\projects
    public static string DefaultProjectsDirectory => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
        ".claude", "projects");

    // The project-folder name Claude derives from a cwd: every character that is
    // not a-z A-Z 0-9 becomes a dash, case is preserved, e.g.
    // C:\Users\ZEPHYRUS G14\Desktop\sessions -> C--Users-ZEPHYRUS-G14-Desktop-sessions
    public static string EncodeCwd(string cwd)
    {
        StringBuilder sb = new(cwd.Length);
        foreach (char c in cwd)
        {
            sb.Append(char.IsAsciiLetterOrDigit(c) ? c : '-');
        }

        return sb.ToString();
    }

    // The newest session id from a set of (id, lastWrite) candidates, or null when
    // there are none, newest by last-write time wins
    public static string? SelectNewestSessionId(IEnumerable<(string Id, DateTimeOffset Modified)> candidates)
    {
        return candidates
            .OrderByDescending(c => c.Modified)
            .Select(c => c.Id)
            .FirstOrDefault();
    }

    // The newest session id for the given cwd, or null when the project folder or a
    // .jsonl is missing
    public static string? FindSessionId(string projectsDirectory, string cwd)
    {
        string folder = Path.Combine(projectsDirectory, EncodeCwd(cwd));
        if (!Directory.Exists(folder))
        {
            return null;
        }

        var candidates = Directory
            .EnumerateFiles(folder, "*.jsonl")
            .Select(f => (Id: Path.GetFileNameWithoutExtension(f),
                          Modified: (DateTimeOffset)File.GetLastWriteTimeUtc(f)));

        return SelectNewestSessionId(candidates);
    }
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

namespace Sessions.Core;

// Builds the wt.exe argument line that reopens a terminal window and its tabs,
// we start wt.exe directly (no shell) so the ; tab separators pass through
// literally, see docs/spikes/terminal.md
public static class WtCommandBuilder
{
    // -w new opens one fresh window, the first tab is implicit, each later tab is a
    // "; new-tab" subcommand, a Claude tab resumes its session, an ssh tab re-runs
    // its command
    public static string Build(TerminalEntry entry)
    {
        ArgumentNullException.ThrowIfNull(entry);

        StringBuilder sb = new("-w new");

        bool first = true;
        foreach (TerminalTab tab in entry.Tabs)
        {
            sb.Append(first ? " " : " ; new-tab ");
            sb.Append(TabArguments(tab));
            first = false;
        }

        return sb.ToString();
    }

    private static string TabArguments(TerminalTab tab)
    {
        StringBuilder sb = new();
        sb.Append("-d ").Append(Quote(tab.Cwd));
        sb.Append(' ').Append(Quote(tab.ShellPath));

        string? command = InnerCommand(tab);
        if (command is not null)
        {
            sb.Append(' ').Append(ShellRun(tab.ShellPath, command));
        }

        return sb.ToString();
    }

    // What to run inside the tab's shell: resume Claude, else an ssh command, else
    // nothing (just open the shell in the folder)
    private static string? InnerCommand(TerminalTab tab)
    {
        if (!string.IsNullOrEmpty(tab.ClaudeSessionId))
        {
            return $"claude --resume {tab.ClaudeSessionId}";
        }

        return string.IsNullOrEmpty(tab.Command) ? null : tab.Command;
    }

    // The shell-specific way to run a command and stay open, cmd keeps the window
    // with /k, PowerShell with -NoExit -Command
    private static string ShellRun(string shellPath, string command)
    {
        string shell = Path.GetFileName(shellPath);
        return string.Equals(shell, "cmd.exe", StringComparison.OrdinalIgnoreCase)
            ? $"/k {Quote(command)}"
            : $"-NoExit -Command {Quote(command)}";
    }

    private static string Quote(string value) => $"\"{value}\"";
}

using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

namespace Sessions.Core;

// Captures and restores a Windows Terminal window with its tabs, each tab's folder
// comes from the hook records (TerminalRecords), a tab running Claude Code resumes
// its session and an ssh tab re-runs its command, see docs/spikes/terminal.md,
// registered before GenericAdapter so WindowsTerminal.exe windows go here first
public sealed class TerminalAdapter : IAdapter
{
    private const string WindowsTerminalExe = "WindowsTerminal.exe";

    private readonly Func<ProcessSnapshot> _snapshot;
    private readonly Func<IReadOnlyList<TerminalRecord>> _readRecords;
    private readonly Func<string, string?> _findClaudeSession;
    private readonly IWindowWaiter _waiter;
    private readonly IWindowPlacer _placer;
    private readonly Action<string> _launch;

    public TerminalAdapter()
        : this(
            ProcessSnapshot.Capture,
            () => TerminalRecords.Read(TerminalRecords.DefaultDirectory),
            cwd => ClaudeSession.FindSessionId(ClaudeSession.DefaultProjectsDirectory, cwd),
            new WindowWaiter(),
            new WindowPlacer(),
            LaunchWt)
    { }

    public TerminalAdapter(
        Func<ProcessSnapshot> snapshot,
        Func<IReadOnlyList<TerminalRecord>> readRecords,
        Func<string, string?> findClaudeSession,
        IWindowWaiter waiter,
        IWindowPlacer placer,
        Action<string> launch)
    {
        _snapshot = snapshot ?? throw new ArgumentNullException(nameof(snapshot));
        _readRecords = readRecords ?? throw new ArgumentNullException(nameof(readRecords));
        _findClaudeSession = findClaudeSession ?? throw new ArgumentNullException(nameof(findClaudeSession));
        _waiter = waiter ?? throw new ArgumentNullException(nameof(waiter));
        _placer = placer ?? throw new ArgumentNullException(nameof(placer));
        _launch = launch ?? throw new ArgumentNullException(nameof(launch));
    }

    public string Id => "terminal";

    public bool CanHandle(WindowInfo window) =>
        window.UnsupportedReason is null && IsWindowsTerminal(window.ExePath);

    public Entry Capture(WindowInfo window)
    {
        ArgumentNullException.ThrowIfNull(window);

        ProcessSnapshot snapshot = _snapshot();
        IReadOnlyList<TerminalRecord> shells =
            TerminalRecords.ForWindowsTerminal(_readRecords(), snapshot, window.ProcessId);

        if (shells.Count == 0)
        {
            throw new CaptureException(
                $"{window.Title}: no recorded shells for this terminal, is the Sessions terminal hook installed?");
        }

        List<TerminalTab> tabs = new();
        foreach (TerminalRecord shell in shells)
        {
            (bool isClaude, string? sshCommand) = TerminalShellInspector.Inspect(snapshot, (uint)shell.Pid);

            string? claudeSessionId = null;
            if (isClaude)
            {
                claudeSessionId = _findClaudeSession(shell.Cwd)
                    ?? throw new CaptureException(
                        $"{window.Title}: Claude Code is running in {shell.Cwd} but no session file was found to resume.");
            }

            tabs.Add(new TerminalTab(shell.Cwd, shell.ShellPath, sshCommand, claudeSessionId));
        }

        return new TerminalEntry(DisplayNameFor(tabs), window.Placement, tabs);
    }

    public void Restore(Entry entry)
    {
        ArgumentNullException.ThrowIfNull(entry);

        if (entry is not TerminalEntry terminal)
        {
            throw new RestoreException($"{entry.DisplayName}: TerminalAdapter cannot restore a {entry.GetType().Name}.");
        }

        string arguments = WtCommandBuilder.Build(terminal);

        try
        {
            _launch(arguments);
        }
        catch (Exception ex)
        {
            throw new RestoreException($"{terminal.DisplayName}: failed to launch Windows Terminal.", ex);
        }

        nint handle = _waiter.WaitForNewWindow(WindowsTerminalExe, terminal.DisplayName);

        if (terminal.Placement is not null)
        {
            _placer.Apply(handle, terminal.Placement, targetElevated: false);
        }
    }

    private static bool IsWindowsTerminal(string? exePath) =>
        exePath is not null &&
        string.Equals(Path.GetFileName(exePath), WindowsTerminalExe, StringComparison.OrdinalIgnoreCase);

    private static string DisplayNameFor(IReadOnlyList<TerminalTab> tabs)
    {
        string first = Path.GetFileName(tabs[0].Cwd.TrimEnd('\\', '/'));
        if (string.IsNullOrEmpty(first))
        {
            first = tabs[0].Cwd;
        }

        return tabs.Count == 1 ? $"Terminal — {first}" : $"Terminal — {first} +{tabs.Count - 1}";
    }

    // Start wt.exe through the shell so the Store execution alias resolves, the
    // arguments carry their own ; tab separators
    private static void LaunchWt(string arguments)
    {
        ProcessStartInfo startInfo = new("wt.exe", arguments) { UseShellExecute = true };
        Process.Start(startInfo);
    }
}

