            new TerminalTab(@"C:\proj", @"C:\pwsh.exe", Command: null, ClaudeSessionId: "abc-123")));

        Assert.Equal(
            "-w new -d \"C:\\proj\" \"C:\\pwsh.exe\" -NoExit -Command \"claude --resume abc-123\"",
            args);
    }

    [Fact]
    public void Build_SshTab_ReRunsCommand()
    {
